  "M26.9004 31.9442H33.6255L36.988 26.0597L33.6255 20.1753H26.9004L30.2629 26.0597L26.9004 31.9442Z",
  "M13.4502 31.9442H20.1753L23.5378 26.0597L26.9004 31.9442L23.5378 37.8287H16.8127L13.4502 31.9442Z",
  "M6.7251 20.1753H13.4502L10.0876 14.2908L13.4502 8.40637H6.7251L3.36255 14.2908L6.7251 20.1753Z",
