/**
 * Marca completa. `role="img"` + `aria-label`: para um leitor de tela isto é uma
 * imagem chamada QLAREO, não seis formas sem nome. Quem já tem o nome do app
 * dito por outro elemento (um <h1>, por exemplo) passa `decorative` e o SVG sai
 * da árvore de acessibilidade em vez de repetir o nome duas vezes.
 */
export function Logo({
  className = "h-7 w-auto",
  decorative = false,
}: {
  className?: string;
  decorative?: boolean;
}) {
  return (
    <svg
      viewBox="0 0 147 41"
      className={className}
      {...(decorative
        ? { "aria-hidden": true as const }
        : { role: "img", "aria-label": "QLAREO" })}
    >
      {MARK_PATHS.map((d) => (
        <path key={d} d={d} className="fill-brand" />
      ))}
      <path d={WORDMARK_PATH} fill="currentColor" />
    </svg>
  );
}

/**
 * Só o símbolo, recortado quadrado e centrado no próprio desenho (os losangos
 * ocupam 35.31 × 35.31 a partir de 2.52, 2.52). Um viewBox quadrado importa:
 * favicon, ícone de app e qualquer lugar que reserve uma caixa 1:1 cortariam o
 * símbolo se ele viesse com a largura do wordmark junto.
 */
export function LogoMark({
  className = "h-6 w-6",
  decorative = true,
}: {
  className?: string;
  decorative?: boolean;
}) {
  return (
    <svg
      viewBox="2.52 2.52 35.31 35.31"
      className={className}
      {...(decorative
        ? { "aria-hidden": true as const }
        : { role: "img", "aria-label": "QLAREO" })}
    >
      {MARK_PATHS.map((d) => (
        <path key={d} d={d} className="fill-brand" />
      ))}
    </svg>
  );
}
